head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.rex_rptname = ""; // Rexpert리포트 파일명
// 화면 리사이징

scwin.userParam;
scwin.testDateSet;
scwin.svrGubun = js_svrGubun; // DR전환시

scwin.gDepCd;
scwin.gEmpNo;
scwin.nowGrd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // round처리
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        await scwin.setCode();

        // 오늘날짜로 초기화시킨다.
        // var today = cGetToday("yyyymmdd");
        // var y_day = cGetMinusDate2(today, 1);     // 하루 전 날짜로     공시총괄팀 요청
        const y_day = $c.ud.fn_get_search_taskdd(dts_TASK_DD, 'A');
        edt_SDate.setValue(y_day);
        edt_EDate.setValue(y_day);
        if (scwin.svrGubun === "dr") {
            // DR일 경우   2011.01.28
            await $c.win.alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
            txb_TR_STATE_CD.setValue("-");
        } else {
            txb_TR_STATE_CD.setValue($c.ud.fn_get_trstatcd(dts_TR_STATE_CD, $c.ut.cGetToday("yyyymmdd")));
        }
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        Grd_com_isur.style.zIndex = 30;
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35401.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.MaxTab_01_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_TASK_DD_OnLoadError
 * @description dts_TASK_DD 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_TASK_DD_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_TASK_DD);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35401.dts_TASK_DD_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35401.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF35401.xml", SCREN_PROCS_TP_CD_07);
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            $c.data.downloadGridViewExcel(grd_Grid2, {fileName: "보통주시가총액40억 미달 종목 목록", type: "8"});
        } else {
            $c.data.downloadGridViewExcel(grd_Grid, {fileName: "종류주식시가총액20억 미달 종목 목록", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        scwin.listSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_CrtMgt_onclick
 * @description 「보정계수관리」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_CrtMgt_onclick = async function() {
    try {
        const options = {
            id: "ULDSTF35402",
            title: "보정계수관리",
            type: "browserPopup",
            width: 505 + 5,
            height: 520 + 30,
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("../lstmgt/ULDSTF35402.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35401.btn_CrtMgt_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35401.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name img_SDate_onclick
 * @description img_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.img_SDate_onclick" });
    }
};

/**
 * @method
 * @name img_EDate_onclick
 * @description img_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.img_EDate_onclick" });
    }
};

/**
 * @method
 * @name btn_ISUR_CD_onclick
 * @description btn_ISUR_CD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ISUR_CD_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.btn_ISUR_CD_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name btn_Print_onclick
 * @description 「인쇄」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Print_onclick = function() {
    try {
        scwin.print();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.btn_Print_onclick" });
    }
};

/**
 * @method
 * @name dts_DEP_CD_1_OnLoadCompleted
 * @description dts_DEP_CD_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DEP_CD_1_OnLoadCompleted = function(rowcount) {
    try {
        // setObjectValue(cmb_DEP_CD_1, js_dep_cd) ;
        cmb_DEP_CD_1.setValue('');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.dts_DEP_CD_1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_1_OnLoadCompleted
 * @description dts_EMP_NO_1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_1_OnLoadCompleted = function(rowcount) {
    try {
        // setObjectValue(cmb_EMP_NO_1, js_emp_no) ;
        cmb_EMP_NO_1.setValue('');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.dts_EMP_NO_1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_DEP_CD_1_onselchange
 * @description cmb_DEP_CD_1 onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_1_onselchange = function() {
    try {
        scwin.gDepCd = cmb_DEP_CD_1.getValue();
        if (scwin.gDepCd === '') {
            cmb_EMP_NO_1.setValue('');
        }
        dts_EMP_NO_1.UseFilter = true;
        dts_EMP_NO_1.Filter();
        dts_EMP_NO_1.sort("DEP_CD", 0);
        // dts_EMP_NO_1.sort(); // W-Craft 주석처리
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.cmb_DEP_CD_1_onselchange" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_1_OnFilter
 * @description EMP NO 1 On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EMP_NO_1_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_EMP_NO_1.getCellData(row, "DEP_CD") === scwin.gDepCd || dts_EMP_NO_1.getCellData(row, "DEP_CD") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35401.dts_EMP_NO_1_OnFilter" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_DEP_CD_1",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_EMP_NO_1",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // setObjectValue(cmb_DEP_CD_1, js_dep_cd) ;
    // setObjectValue(cmb_EMP_NO_1, js_emp_no) ;
    cmb_DEP_CD_1.setValue('');
    cmb_EMP_NO_1.setValue('');
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    let url = "";
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        url = "/listingCommon.do?SCREN_ID=" + "ULDSTF35401.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=MKTCAPCOND_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.mktcapcond.cmstk.list" + "&{P}param01=" + txb_ISUR_CD.getValue() + // 법인코드
            "&{P}param02=" + txb_ISUR_CD.getValue() + // 법인코드
            "&{P}param03=" + edt_SDate.getValue() + // 시작일자
            "&{P}param04=" + edt_EDate.getValue() + // 종료일자
            "&{P}param05=" + cmb_DEP_CD_1.getValue() + "&{P}param06=" + cmb_DEP_CD_1.getValue() + "&{P}param07=" + cmb_EMP_NO_1.getValue() + "&{P}param08=" + cmb_EMP_NO_1.getValue();
        scwin.nowGrd = grd_Grid2;
    } else {
        url = "/listingCommon.do?SCREN_ID=" + "ULDSTF35401.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=MKTCAPCOND_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.mktcapcond.knstk.list" + "&{P}param01=" + txb_ISUR_CD.getValue() + // 법인코드
            "&{P}param02=" + txb_ISUR_CD.getValue() + // 법인코드
            "&{P}param03=" + edt_SDate.getValue() + // 시작일자
            "&{P}param04=" + edt_EDate.getValue() + // 종료일자
            "&{P}param05=" + cmb_DEP_CD_1.getValue() + "&{P}param06=" + cmb_DEP_CD_1.getValue() + "&{P}param07=" + cmb_EMP_NO_1.getValue() + "&{P}param08=" + cmb_EMP_NO_1.getValue();
        scwin.nowGrd = grd_Grid;
    }
    dts_List.DataID = encodeURI(url);
    dts_List.reset();

};

/**
 * @method
 * @name setFromToDate
 * @description from, to 날짜에 기간구분선택에 따른 날짜 셋팅하기 - 기간구분 : pTp - from 객체 이름 : pObjFrom - to 객체 이름 : pObjTo
 * @param {String} pTp pTp
 * @param {*} pObjFrom pObjFrom
 * @param {*} pObjTo pObjTo
 * @returns {void}
 * @hidden N
 */
scwin.setFromToDate = function(pTp, pObjFrom, pObjTo) {
    // 1주일^1,1개월^2,3개월^3,6개월^4,1년^5,2년^6
    let vFrom = "";
    let vTo = pObjTo.getValue();
    // alert(vTo);

    if (vTo === '') {
        // 값이 없으면 현재일 기준으로 계산
        vTo = $c.ut.cGetToday("yyyymmdd");
    }
    if (pTp === 0) {
        vFrom = $c.ut.cGetMinusDate2(vTo, 0); // 하루(동일날짜)로

    } else if (pTp === 1) {
        vFrom = $c.ut.cGetMinusDate2(vTo, 7); // 일주일전

    } else if (pTp === 2) {
        // 1개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 1);
    } else if (pTp === 3) {
        // 3개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 3);
    } else if (pTp === 4) {
        // 6개월전
        vFrom = $c.ut.cGetMinusMonth(vTo.substring(0, 4), vTo.substring(4, 6), vTo.substring(6, 8), 6);
    } else if (pTp === 5) {
        // 1년전
        vFrom = $c.ut.cGetMinusYear(vTo, 1);
    } else if (pTp === 6) {
        // 2년전
        vFrom = $c.ut.cGetMinusYear(vTo, 2);
    }
    pObjFrom.setValue(vFrom);
    pObjTo.setValue(vTo);
};

