            "&{P}param02=" + txb_ISUR_CD.getValue() + // 법인코드
            "&{P}param03=" + edt_SDate.getValue() + // 시작일자
            "&{P}param04=" + edt_EDate.getValue() + // 종료일자
            "&{P}param05=" + cmb_DEP_CD_1.getValue() + "&{P}param06=" + cmb_DEP_CD_1.getValue() + "&{P}param07=" + cmb_EMP_NO_1.getValue() + "&{P}param08=" + cmb_EMP_NO_1.getValue();
    }
    dts_report.DataID = encodeURI(url);
    dts_report.reset();
    const dataFormatArr = ["TASK_DD:FormatDateEx", "LIST_SHRS:FormatNumberEx", "TDD_CLSPRC:FormatNumberEx", "MKTCAP:FormatNumberEx", "CORRCT_MKTCAP:FormatNumberEx", "FST_LACK_DD:FormatDateEx"];
    const jsonData = $c.rpt.fn_make_dtsToJson1_wdf(dts_report, dataFormatArr);
    const userParam = [{
        uid: "SDate",
